{
  "device_comments": {
    "X0": "start",
    "X1": "stop",
    "Y0": "motor"
  },
  "rungs": [
    {
      "rung_id": 1,
      "debug_note": "stop input is explicitly provided by the user",
      "header_element": null,
      "branches": [
        {
          "branch_id": 1,
          "y_offset_level": 0,
          "inputs": [
            {
              "type": "parallel_block",
              "branches": [
                [
                  {
                    "type": "NO",
                    "address": "X0",
                    "label": "start"
                  }
                ],
                [
                  {
                    "type": "NO",
                    "address": "Y0",
                    "label": "seal-in"
                  }
                ]
              ]
            },
            {
              "type": "NC",
              "address": "X1",
              "label": "stop"
            }
          ],
          "outputs": [
            {
              "type": "COIL",
              "address": "Y0",
              "label": "motor"
            }
          ]
        }
      ]
    }
  ]
}

{
  "device_comments": {
    "X0": "forward",
    "X1": "reverse",
    "X2": "stop",
    "Y0": "forward",
    "Y1": "reverse",
    "T200": "forward_to_reverse_delay",
    "T201": "reverse_to_forward_delay"
  },
  "rungs": [
    {
      "rung_id": 1,
      "debug_note": "stop input is explicitly provided by the user",
      "header_element": null,
      "branches": [
        {
          "branch_id": 1,
          "y_offset_level": 0,
          "inputs": [
            {
              "type": "parallel_block",
              "branches": [
                [
                  {
                    "type": "NO",
                    "address": "X0",
                    "label": "forward"
                  }
                ],
                [
                  {
                    "type": "NO",
                    "address": "Y0",
                    "label": "seal-in"
                  }
                ]
              ]
            },
            {
              "type": "NC",
              "address": "X2",
              "label": "stop"
            },
            {
              "type": "NC",
              "address": "Y1",
              "label": "reverse interlock"
            },
            {
              "type": "NC",
              "address": "T200",
              "label": "direction delay"
            }
          ],
          "outputs": [
            {
              "type": "COIL",
              "address": "Y0",
              "label": "forward"
            },
            {
              "type": "TIMER",
              "address": "T200",
              "value": "K2",
              "label": "20ms delay"
            }
          ]
        }
      ]
    },
    {
      "rung_id": 2,
      "debug_note": "stop input is explicitly provided by the user",
      "header_element": null,
      "branches": [
        {
          "branch_id": 1,
          "y_offset_level": 0,
          "inputs": [
            {
              "type": "parallel_block",
              "branches": [
                [
                  {
                    "type": "NO",
                    "address": "X1",
                    "label": "reverse"
                  }
                ],
                [
                  {
                    "type": "NO",
                    "address": "Y1",
                    "label": "seal-in"
                  }
                ]
              ]
            },
            {
              "type": "NC",
              "address": "X2",
              "label": "stop"
            },
            {
              "type": "NC",
              "address": "Y0",
              "label": "forward interlock"
            },
            {
              "type": "NC",
              "address": "T201",
              "label": "direction delay"
            }
          ],
          "outputs": [
            {
              "type": "COIL",
              "address": "Y1",
              "label": "reverse"
            },
            {
              "type": "TIMER",
              "address": "T201",
              "value": "K2",
              "label": "20ms delay"
            }
          ]
        }
      ]
    }
  ]
}

{
  "device_comments": {"M8002":"开机初始化","Y0":"绿灯","Y1":"黄灯","Y2":"红灯","T0":"绿灯延时20s","T1":"黄灯延时3s","T2":"红灯延时5s","D0":"步进号"},
  "rungs": [
    {"rung_id":1,"header_element":null,"branches":[{"branch_id":1,"y_offset_level":0,
      "inputs":[{"type":"P","address":"M8002","label":"开机脉冲"}],
      "outputs":[{"type":"APP_INSTR","opcode":"MOV","operands":["K1","D0"],"label":"初始化→步骤1"}]
    }]},
    {"rung_id":2,"header_element":{"type":"BLOCK_INPUT","expression":"= D0 K1"},"branches":[{"branch_id":1,"y_offset_level":0,
      "inputs":[{"type":"NO","address":"M8000","label":"常开"}],
      "outputs":[{"type":"COIL","address":"Y0","label":"绿灯"},{"type":"TIMER","address":"T0","value":"K200","label":"20秒"}]
    },{"branch_id":2,"y_offset_level":1,
      "inputs":[{"type":"NO","address":"T0","label":"延时到"}],
      "outputs":[{"type":"APP_INSTR","opcode":"MOV","operands":["K2","D0"],"label":"→步骤2"}]
    }]},
    {"rung_id":3,"header_element":{"type":"BLOCK_INPUT","expression":"= D0 K2"},"branches":[{"branch_id":1,"y_offset_level":0,
      "inputs":[{"type":"NO","address":"M8000","label":"常开"}],
      "outputs":[{"type":"COIL","address":"Y1","label":"黄灯"},{"type":"TIMER","address":"T1","value":"K30","label":"3秒"}]
    },{"branch_id":2,"y_offset_level":1,
      "inputs":[{"type":"NO","address":"T1","label":"延时到"}],
      "outputs":[{"type":"APP_INSTR","opcode":"MOV","operands":["K3","D0"],"label":"→步骤3"}]
    }]},
    {"rung_id":4,"header_element":{"type":"BLOCK_INPUT","expression":"= D0 K3"},"branches":[{"branch_id":1,"y_offset_level":0,
      "inputs":[{"type":"NO","address":"M8000","label":"常开"}],
      "outputs":[{"type":"COIL","address":"Y2","label":"红灯"},{"type":"TIMER","address":"T2","value":"K50","label":"5秒"}]
    },{"branch_id":2,"y_offset_level":1,
      "inputs":[{"type":"NO","address":"T2","label":"延时到"}],
      "outputs":[{"type":"APP_INSTR","opcode":"MOV","operands":["K1","D0"],"label":"循环回步骤1"}]
    }]}
  ]
}

{
  "device_comments": {"X0":"计数输入","C0":"计数器","Y0":"到位输出","X1":"手动复位"},
  "rungs": [
    {"rung_id":1,"header_element":null,"branches":[{"branch_id":1,"y_offset_level":0,
      "inputs":[{"type":"P","address":"X0","label":"计数脉冲"}],
      "outputs":[{"type":"COUNTER","address":"C0","value":"K5","label":"计5次"}]
    }]},
    {"rung_id":2,"header_element":null,"branches":[{"branch_id":1,"y_offset_level":0,
      "inputs":[{"type":"NO","address":"C0","label":"计数到"}],
      "outputs":[{"type":"COIL","address":"Y0","label":"到位输出"}]
    }]},
    {"rung_id":3,"header_element":null,"branches":[{"branch_id":1,"y_offset_level":0,
      "inputs":[{"type":"P","address":"X1","label":"复位"}],
      "outputs":[{"type":"APP_INSTR","opcode":"RST","operands":["C0"],"label":"复位计数器"}]
    }]}
  ]
}

{
  "device_comments": {
    "X0": "start",
    "Y0": "pulse_output",
    "Y1": "done_latch",
    "M20": "pulse_request",
    "M8029": "pulse_done"
  },
  "rungs": [
    {
      "rung_id": 1,
      "header_element": null,
      "branches": [
        {
          "branch_id": 1,
          "y_offset_level": 0,
          "inputs": [
            {
              "type": "P",
              "address": "X0",
              "label": "start edge"
            }
          ],
          "outputs": [
            {
              "type": "APP_INSTR",
              "opcode": "SET",
              "operands": [
                "M20"
              ],
              "label": "set request"
            }
          ]
        }
      ]
    },
    {
      "rung_id": 2,
      "debug_note": "PLSY and M8029 completion use sibling branches in one rung",
      "header_element": null,
      "shared_inputs": [
        {
          "type": "NO",
          "address": "M20",
          "label": "pulse request"
        }
      ],
      "branches": [
        {
          "branch_id": 1,
          "y_offset_level": 0,
          "inputs": [],
          "outputs": [
            {
              "type": "APP_INSTR",
              "opcode": "PLSY",
              "operands": [
                "K1000",
                "K5000",
                "Y0"
              ],
              "label": "1000Hz 5000 pulses"
            }
          ]
        },
        {
          "branch_id": 2,
          "y_offset_level": 1,
          "inputs": [
            {
              "type": "NO",
              "address": "M8029",
              "label": "pulse done"
            }
          ],
          "outputs": [
            {
              "type": "APP_INSTR",
              "opcode": "SET",
              "operands": [
                "Y1"
              ],
              "label": "done latch"
            },
            {
              "type": "APP_INSTR",
              "opcode": "RST",
              "operands": [
                "M20"
              ],
              "label": "clear request"
            }
          ]
        }
      ]
    }
  ]
}

{
  "device_comments": {"M8002":"开机","M8000":"常开","D500":"PID首地址","D202":"目标值","D101":"测量值","D102":"输出量"},
  "rungs": [
    {"rung_id":1,"debug_note":"PID首地址D500,独占D500-D524","header_element":null,"branches":[{"branch_id":1,"y_offset_level":0,
      "inputs":[{"type":"P","address":"M8002","label":"开机初始化"}],
      "outputs":[
        {"type":"APP_INSTR","opcode":"MOV","operands":["K100","D500"],"label":"Ts=100(采样周期)"},
        {"type":"APP_INSTR","opcode":"MOV","operands":["K0","D501"],"label":"方向0=正动作"},
        {"type":"APP_INSTR","opcode":"MOV","operands":["K100","D503"],"label":"Kp"},
        {"type":"APP_INSTR","opcode":"MOV","operands":["K50","D504"],"label":"Ti=5s(单位100ms)"},
        {"type":"APP_INSTR","opcode":"MOV","operands":["K0","D505"],"label":"Td=0"}
      ]
    }]},
    {"rung_id":2,"header_element":null,"branches":[{"branch_id":1,"y_offset_level":0,
      "inputs":[{"type":"NO","address":"M8000","label":"常开"}],
      "outputs":[{"type":"APP_INSTR","opcode":"PID","operands":["D202","D101","D500","D102"],"label":"PID运算"}]
    }]},
    {"rung_id":3,"header_element":null,"branches":[{"branch_id":1,"y_offset_level":0,
      "inputs":[{"type":"NO","address":"M8000","label":"常开"},{"type":"COMPARE","expression":"< D102 K0","label":"防负溢出"}],
      "outputs":[{"type":"APP_INSTR","opcode":"MOV","operands":["K0","D102"],"label":"归零限幅"}]
    }]}
  ]
}

{
  "device_comments": {"M8013":"1秒内部时钟","M3":"1Hz闪烁位","M4":"0.5Hz闪烁位","T10":"OFF相1秒","T11":"ON相1秒"},
  "rungs": [
    {"rung_id":1,"debug_note":"M8013完整周期1秒，直接得到约1Hz闪烁","header_element":null,"branches":[{"branch_id":1,"y_offset_level":0,"inputs":[{"type":"NO","address":"M8013","label":"1秒时钟"}],"outputs":[{"type":"COIL","address":"M3","label":"1Hz闪烁"}]}]},
    {"rung_id":2,"debug_note":"T10为FX3U 100ms基准，K10=1秒；M4置位后本使能自动断开","header_element":null,"branches":[{"branch_id":1,"y_offset_level":0,"inputs":[{"type":"NC","address":"M4","label":"OFF相"}],"outputs":[{"type":"TIMER","address":"T10","value":"K10","label":"OFF相1秒"}]}]},
    {"rung_id":3,"header_element":null,"branches":[{"branch_id":1,"y_offset_level":0,"inputs":[{"type":"NO","address":"T10","label":"OFF相完成"}],"outputs":[{"type":"APP_INSTR","opcode":"SET","operands":["M4"],"label":"进入ON相"}]}]},
    {"rung_id":4,"debug_note":"M4复位后T11使能自动断开，形成1秒ON+1秒OFF","header_element":null,"branches":[{"branch_id":1,"y_offset_level":0,"inputs":[{"type":"NO","address":"M4","label":"ON相"}],"outputs":[{"type":"TIMER","address":"T11","value":"K10","label":"ON相1秒"}]}]},
    {"rung_id":5,"header_element":null,"branches":[{"branch_id":1,"y_offset_level":0,"inputs":[{"type":"NO","address":"T11","label":"ON相完成"}],"outputs":[{"type":"APP_INSTR","opcode":"RST","operands":["M4"],"label":"返回OFF相"}]}]}
  ]
}

{
  "device_comments": {"X3":"故障信号","Y10":"报警灯","Y11":"蜂鸣器","M50":"报警标志","M51":"已确认","X13":"消音按钮","X14":"复位按钮","M8013":"1s时钟"},
  "rungs": [
    {"rung_id":1,"header_element":null,"branches":[{"branch_id":1,"y_offset_level":0,
      "inputs":[{"type":"NO","address":"X3","label":"故障"}],
      "outputs":[{"type":"APP_INSTR","opcode":"SET","operands":["M50"],"label":"报警标志"}]
    }]},
    {"rung_id":2,"debug_note":"一个Y10线圈汇合未确认闪烁与已确认常亮条件","header_element":null,"branches":[{"branch_id":1,"y_offset_level":0,
      "inputs":[{"type":"parallel_block","branches":[[{"type":"NO","address":"M50","label":"报警中"},{"type":"NC","address":"M51","label":"未确认"},{"type":"NO","address":"M8013","label":"1s时钟"}],[{"type":"NO","address":"M50","label":"报警中"},{"type":"NO","address":"M51","label":"已确认"}]]}],
      "outputs":[{"type":"COIL","address":"Y10","label":"报警灯"}]
    }]},
    {"rung_id":3,"header_element":null,"branches":[{"branch_id":1,"y_offset_level":0,
      "inputs":[{"type":"NO","address":"M50","label":"报警中"},{"type":"NC","address":"M51","label":"未确认"},{"type":"NO","address":"M8013","label":"1s时钟"}],
      "outputs":[{"type":"COIL","address":"Y11","label":"蜂鸣器"}]
    }]},
    {"rung_id":4,"header_element":null,"branches":[{"branch_id":1,"y_offset_level":0,
      "inputs":[{"type":"P","address":"X13","label":"消音"}],
      "outputs":[{"type":"APP_INSTR","opcode":"SET","operands":["M51"],"label":"确认"}]
    }]},
    {"rung_id":5,"header_element":null,"branches":[{"branch_id":1,"y_offset_level":0,
      "inputs":[{"type":"NC","address":"X3","label":"故障消除"},{"type":"P","address":"X14","label":"复位"}],
      "outputs":[{"type":"APP_INSTR","opcode":"RST","operands":["M50"],"label":""},{"type":"APP_INSTR","opcode":"RST","operands":["M51"],"label":""}]
    }]}
  ]
}
